enum AppError {
    NotFound(String),
    Denied,
}
fn find(id: u32) -> Result<String, AppError> {
    if id == 1 { Ok("goose".into()) } else { Err(AppError::NotFound(format!("id {}", id))) }
}
fn main() {
    match find(2) {
        Ok(s) => println!("เจอ {}", s),
        Err(AppError::NotFound(m)) => println!("ไม่เจอ: {}", m),
        Err(AppError::Denied) => println!("ห้าม"),
    }
}

