fn main() {
    let mut delay = 1;
    let mut tries = 0;
    while tries < 3 {
        tries += 1;
        if tries == 3 {
            break;
        }
        delay *= 2;
    }
    println!("สำเร็จรอบ {} delay {}", tries, delay);
}

